package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBase;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.impl.BeanPropertyMap;
import com.fasterxml.jackson.databind.deser.impl.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.std.StdDelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.exc.IgnoredPropertyException;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedType;
import com.fasterxml.jackson.databind.introspect.BeanDescription;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_resolve_TriageGen1Test {

    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private ValueInstantiator valueInstantiator;
    private BeanDescription beanDescription;
    private BeanDeserializerBuilder builder;
    private BeanDeserializerBase beanDeserializer;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        valueInstantiator = mock(ValueInstantiator.class);
        beanDescription = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);

        when(ctxt.getConfig()).thenReturn(config);
        when(beanDescription.getBeanClass()).thenReturn(Object.class);

        // Use a spy or a concrete subclass since BeanDeserializerBase is abstract
        beanDeserializer = spy(new BeanDeserializerBase(builder, beanDescription, 
                new BeanPropertyMap(Collections.emptyList()), Collections.emptyMap(), 
                Collections.emptySet(), true, false) {
            @Override
            public JsonDeserializer<Object> unwrappingDeserializer(NameTransformer unwrapper) { return null; }
            @Override
            protected JsonDeserializer<Object> findConvertingDeserializer(DeserializationContext ctxt, SettableBeanProperty prop) { return null; }
            @Override
            protected JsonDeserializer findDeserializer(DeserializationContext ctxt, JavaType type, SettableBeanProperty prop) { return null; }
            @Override
            protected BeanDeserializerBase asArrayDeserializer() { return null; }
            @Override
            protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) { return null; }
            @Override
            public Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) { return null; }
        });
    }

    @Test
    public void testResolve_SimplePath() throws JsonMappingException {
        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        when(prop.hasValueDeserializer()).thenReturn(true);
        when(prop.getValueDeserializer()).thenReturn(mock(JsonDeserializer.class));
        when(prop.getType()).thenReturn(mock(JavaType.class));

        setupBeanProperties(Collections.singletonList(prop));

        when(valueInstantiator.canCreateFromObjectWith()).thenReturn(false);

        beanDeserializer.resolve(ctxt);

        verify(ctxt, atLeastOnce()).handlePrimaryContextualization(any(), any(), any());
    }

    @Test
    public void testResolve_WithCreatorProps() throws JsonMappingException {
        when(valueInstantiator.canCreateFromObjectWith()).thenReturn(true);
        SettableBeanProperty creatorProp = mock(SettableBeanProperty.class);
        when(valueInstantiator.getFromObjectArguments(config)).thenReturn(new SettableBeanProperty[]{creatorProp});

        beanDeserializer.resolve(ctxt);

        verify(valueInstantiator).getFromObjectArguments(config);
    }

    @Test
    public void testResolve_WithDelegateCreator() throws JsonMappingException {
        when(valueInstantiator.canCreateUsingDelegate()).thenReturn(true);
        JavaType delegateType = mock(JavaType.class);
        when(valueInstantiator.getDelegateType(config)).thenReturn(delegateType);

        // Mocking the internal _findDelegateDeserializer via spy is tricky, 
        // but we can trigger the IllegalArgumentException path
        when(valueInstantiator.getDelegateType(config)).thenReturn(null);

        try {
            beanDeserializer.resolve(ctxt);
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("Invalid delegate-creator"));
        }
    }

    @Test
    public void testResolve_WithArrayDelegateCreator() throws JsonMappingException {
        when(valueInstantiator.canCreateUsingArrayDelegate()).thenReturn(true);
        JavaType delegateType = mock(JavaType.class);
        when(valueInstantiator.getArrayDelegateType(config)).thenReturn(delegateType);

        // Trigger error path
        when(valueInstantiator.getArrayDelegateType(config)).thenReturn(null);

        try {
            beanDeserializer.resolve(ctxt);
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("Invalid array-delegate-creator"));
        }
    }

    @Test
    public void testResolve_UnwrappedProperty() throws JsonMappingException {
        SettableBeanProperty origProp = mock(SettableBeanProperty.class);
        SettableBeanProperty unwrappedProp = mock(SettableBeanProperty.class);

        when(origProp.hasValueDeserializer()).thenReturn(true);
        when(origProp.getValueDeserializer()).thenReturn(mock(JsonDeserializer.class));

        setupBeanProperties(Collections.singletonList(origProp));

        // Mock the internal _resolveUnwrappedProperty call
        doReturn(unwrappedProp).when(beanDeserializer)._resolveUnwrappedProperty(any(), any());

        beanDeserializer.resolve(ctxt);

        // If unwrapped is found, _nonStandardCreation becomes true via unwrapped != null
        // and _vanillaProcessing becomes false.
    }

    @Test
    public void testResolve_ExternalProperty() throws JsonMappingException {
        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        TypeDeserializer typeDeser = mock(TypeDeserializer.class);

        when(prop.hasValueDeserializer()).thenReturn(true);
        when(prop.getValueDeserializer()).thenReturn(mock(JsonDeserializer.class));
        when(prop.hasValueTypeDeserializer()).thenReturn(true);
        when(prop.getValueTypeDeserializer()).thenReturn(typeDeser);
        when(typeDeser.getTypeInclusion()).thenReturn(JsonTypeInfo.As.EXTERNAL_PROPERTY);

        setupBeanProperties(Collections.singletonList(prop));

        beanDeserializer.resolve(ctxt);

        // Should trigger extTypes logic
    }

    @Test
    public void testResolve_AnySetter() throws JsonMappingException {
        SettableBeanProperty anySetter = mock(SettableBeanProperty.class);
        when(anySetter.hasValueDeserializer()).thenReturn(false);
        when(anySetter.getType()).thenReturn(mock(JavaType.class));
        when(anySetter.getProperty()).thenReturn(mock(PropertyName.class));

        // Use reflection or a specialized spy to set the private _anySetter field if needed,
        // but since we can't easily access private fields in a standard way without reflection,
        // we assume a scenario where it is provided.
        // For the purpose of this test, we simulate the logic by ensuring the method doesn't crash.

        beanDeserializer.resolve(ctxt);
    }

    private void setupBeanProperties(List<SettableBeanProperty> props) {
        // Since _beanProperties is likely private, we assume the constructor or a setter
        // was used to populate it. In a real test, we'd use reflection to inject into the spy.
        try {
            java.lang.reflect.Field field = BeanDeserializerBase.class.getDeclaredField("_beanProperties");
            field.setAccessible(true);
            field.set(beanDeserializer, new BeanPropertyMap(props));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    // Mocking helper for TypeDeserializer
    interface TypeDeserializer extends JsonDeserializer<Object> {
        JsonTypeInfo.As getTypeInclusion();
    }
}
